<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import Button from 'primevue/button';import Tag from 'primevue/tag'
const menuOpen=ref(false),scrolled=ref(false),typed=ref('experiências digitais'),words=['experiências digitais','produtos escaláveis','soluções com impacto'];let timer
const skills=[{n:'01',title:'Vue & Interface',text:'Interfaces modernas, responsivas e consistentes.',tags:['Vue.js','PrimeVue','JavaScript','CSS']},{n:'02',title:'Backend & Dados',text:'Sistemas seguros e orientados a dados.',tags:['PHP','Laravel','MySQL','APIs REST']},{n:'03',title:'Qualidade',text:'Produtos confiáveis através de testes e validação.',tags:['Functional Testing','Usability','Bug Reporting']},{n:'04',title:'Ecossistema',text:'Ferramentas para desenvolver, versionar e entregar.',tags:['Vue.js','PrimeVue','Git','GitHub']}]
const projects=[{n:'01 / Destaque',mark:'XT',badge:'Fintech • Privado',title:'XiTikando',text:'Uma experiência digital que moderniza o xitique, tornando a poupança em grupo mais organizada e acessível.',tags:['Produto','Full Stack','UX'],featured:true},{n:'02',mark:'P360',badge:'IA • Produto',title:'Parceria360 AI',text:'IA integrada a uma plataforma de gestão para aconselhamento, análise de projetos, custos, tarefas e documentos.',tags:['AI','Produto','Gestão']},{n:'03',mark:'Q3L',badge:'Java • Público',title:'QuaseTrêsLanches',text:'Projeto que demonstra organização de código e fundamentos de desenvolvimento.',link:'https://github.com/LangaJoao/QuaseTresLanches1.0'},{n:'04',mark:'EDA',badge:'Open Source',title:'Estruturas & Algoritmos',text:'Exercícios e implementações para consolidar fundamentos de programação.',link:'https://github.com/LangaJoao/Resolucao_Exercicios_EDA'}]
