let reveal,onScroll,onMove
onMounted(()=>{document.documentElement.classList.add('app-dark');reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>reveal.observe(e));onScroll=()=>scrolled.value=scrollY>25;onMove=e=>{const g=document.querySelector('.cursor-glow');if(g){g.style.left=e.clientX+'px';g.style.top=e.clientY+'px'}};addEventListener('scroll',onScroll,{passive:true});addEventListener('pointermove',onMove,{passive:true});let w=0,c=0,del=false;const type=()=>{const word=words[w];typed.value=del?word.slice(0,--c):word.slice(0,++c);let speed=del?45:75;if(!del&&c===word.length){del=true;speed=1700}else if(del&&c===0){del=false;w=(w+1)%words.length;speed=300}timer=setTimeout(type,speed)};timer=setTimeout(type,800)})
onBeforeUnmount(()=>{clearTimeout(timer);removeEventListener('scroll',onScroll);removeEventListener('pointermove',onMove);reveal?.disconnect()})
